                  <div className="space-y-1.5">
                    <Label>{t("skills.note")}</Label>
                    <Input value={evForm.note} onChange={(e) => setEvForm({ ...evForm, note: e.target.value })} placeholder={t("skills.notePlaceholder")} />
                  </div>
