"use client";

import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";
import { api, fmtDate } from "@/lib/client";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Sheet, SheetContent, SheetFooter, SheetHeader, SheetTitle,
} from "@/components/ui/sheet";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { Pencil, Plus, Trash2 } from "lucide-react";
import { useT } from "@/lib/i18n/provider";

type Project = {
  id: string;
  name: string;
  role?: string | null;
  experienceId?: string | null;
  experience?: { id: string; company: string } | null;
  startDate?: string | null;
  endDate?: string | null;
  description?: string | null;
  outcome?: string | null;
  techStack: string[];
  skills: { skill: { id: string; name: string } }[];
};

type ExperienceOption = { id: string; company: string; title: string };

const NONE = "__none__";
const EMPTY_FORM = {
  name: "", role: "", experienceId: NONE, startDate: "", endDate: "",
  description: "", outcome: "", techStack: "",
};

export function ProjectTab() {
  const t = useT();
  const [items, setItems] = useState<Project[] | null>(null);
  const [experiences, setExperiences] = useState<ExperienceOption[]>([]);
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState<Project | null>(null);
  const [form, setForm] = useState(EMPTY_FORM);
  const [saving, setSaving] = useState(false);

  const load = useCallback(async () => {
    const [projRes, expRes] = await Promise.all([
      api<{ data: Project[] }>("/projects"),
      api<{ data: ExperienceOption[] }>("/experiences"),
    ]);
    if (projRes) setItems(projRes.data);
    if (expRes) setExperiences(expRes.data);
  }, []);

  useEffect(() => { void load(); }, [load]);

  function openCreate() {
    setEditing(null);
    setForm(EMPTY_FORM);
    setOpen(true);
  }

  function openEdit(p: Project) {
    setEditing(p);
    setForm({
      name: p.name,
      role: p.role ?? "",
      experienceId: p.experienceId ?? NONE,
      startDate: fmtDate(p.startDate),
      endDate: fmtDate(p.endDate),
      description: p.description ?? "",
      outcome: p.outcome ?? "",
      techStack: p.techStack.join(", "),
    });
    setOpen(true);
  }

  async function save() {
    if (!form.name) {
      toast.error(t("project.requiredError"));
      return;
    }
    setSaving(true);
    const body = JSON.stringify({
      name: form.name,
      role: form.role || undefined,
      experienceId: form.experienceId === NONE ? null : form.experienceId,
      startDate: form.startDate || null,
      endDate: form.endDate || null,
      description: form.description || undefined,
      outcome: form.outcome || undefined,
      techStack: form.techStack.split(/[,，]/).map((s) => s.trim()).filter(Boolean),
      skillIds: editing ? editing.skills.map((s) => s.skill.id) : [],
    });
    const res = editing
      ? await api(`/projects/${editing.id}`, { method: "PUT", body })
      : await api("/projects", { method: "POST", body });
    setSaving(false);
    if (res) {
      toast.success(editing ? t("common.updated") : t("common.added"));
      setOpen(false);
      void load();
    }
  }

  async function remove(id: string) {
    const res = await api(`/projects/${id}`, { method: "DELETE" });
    if (res) {
      toast.success(t("common.deleted"));
      void load();
    }
  }

  if (!items) {
    return <div className="grid gap-3 pt-4 md:grid-cols-2">{[1, 2].map((i) => <Skeleton key={i} className="h-36" />)}</div>;
  }

  return (
    <div className="space-y-3 pt-2">
      <div className="flex justify-end">
        <Button size="sm" onClick={openCreate}><Plus className="size-4" /> {t("project.add")}</Button>
      </div>

      {items.length === 0 && (
        <Card><CardContent className="py-10 text-center text-sm text-muted-foreground">
          {t("project.empty")}
        </CardContent></Card>
      )}

      <div className="grid gap-3 md:grid-cols-2">
        {items.map((p) => (
          <Card key={p.id}>
            <CardContent className="space-y-2 py-4">
              <div className="flex items-start justify-between gap-2">
                <div className="min-w-0">
                  <p className="truncate font-medium">{p.name}</p>
                  <p className="text-xs text-muted-foreground">
                    {p.role && `${p.role} · `}
                    {p.experience?.company ?? t("project.personal")}
                    {p.startDate && ` · ${fmtDate(p.startDate).slice(0, 7)}${p.endDate ? ` ~ ${fmtDate(p.endDate).slice(0, 7)}` : ` ~ ${t("common.present")}`}`}
                  </p>
                </div>
                <div className="flex shrink-0 gap-1">
                  <Button variant="ghost" size="icon" className="size-8" onClick={() => openEdit(p)}>
                    <Pencil className="size-3.5" />
                  </Button>
                  <AlertDialog>
                    <AlertDialogTrigger asChild>
                      <Button variant="ghost" size="icon" className="size-8"><Trash2 className="size-3.5" /></Button>
                    </AlertDialogTrigger>
                    <AlertDialogContent>
                      <AlertDialogHeader>
                        <AlertDialogTitle>{t("project.deleteTitle", { name: p.name })}</AlertDialogTitle>
                        <AlertDialogDescription>{t("project.deleteDesc")}</AlertDialogDescription>
                      </AlertDialogHeader>
                      <AlertDialogFooter>
                        <AlertDialogCancel>{t("common.cancel")}</AlertDialogCancel>
                        <AlertDialogAction onClick={() => remove(p.id)}>{t("common.delete")}</AlertDialogAction>
                      </AlertDialogFooter>
                    </AlertDialogContent>
                  </AlertDialog>
                </div>
              </div>
              {p.outcome && <p className="line-clamp-2 text-sm text-muted-foreground">{p.outcome}</p>}
              {(p.techStack.length > 0 || p.skills.length > 0) && (
                <div className="flex flex-wrap gap-1.5">
                  {p.techStack.map((t) => <Badge key={t} variant="outline" className="font-normal">{t}</Badge>)}
                  {p.skills.map((s) => <Badge key={s.skill.id} variant="secondary" className="font-normal">{s.skill.name}</Badge>)}
                </div>
              )}
            </CardContent>
          </Card>
        ))}
      </div>

      <Sheet open={open} onOpenChange={setOpen}>
        <SheetContent className="overflow-y-auto sm:max-w-md">
          <SheetHeader><SheetTitle>{editing ? t("project.editTitle") : t("project.addTitle")}</SheetTitle></SheetHeader>
          <div className="space-y-4 px-4">
            <div className="space-y-1.5">
              <Label>{t("project.name")}</Label>
              <Input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1.5">
                <Label>{t("project.role")}</Label>
                <Input value={form.role} onChange={(e) => setForm({ ...form, role: e.target.value })} />
              </div>
              <div className="space-y-1.5">
                <Label>{t("project.belongsTo")}</Label>
                <Select value={form.experienceId} onValueChange={(v) => setForm({ ...form, experienceId: v })}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value={NONE}>{t("project.personal")}</SelectItem>
                    {experiences.map((e) => (
                      <SelectItem key={e.id} value={e.id}>{e.company} · {e.title}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1.5">
                <Label>{t("project.startDate")}</Label>
                <Input type="date" value={form.startDate} onChange={(e) => setForm({ ...form, startDate: e.target.value })} />
              </div>
              <div className="space-y-1.5">
                <Label>{t("project.endDate")}</Label>
                <Input type="date" value={form.endDate} onChange={(e) => setForm({ ...form, endDate: e.target.value })} />
              </div>
            </div>
            <div className="space-y-1.5">
              <Label>{t("project.description")}</Label>
              <Textarea rows={3} value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} />
            </div>
            <div className="space-y-1.5">
              <Label>{t("project.outcome")}</Label>
              <Textarea rows={2} value={form.outcome} onChange={(e) => setForm({ ...form, outcome: e.target.value })} />
            </div>
            <div className="space-y-1.5">
              <Label>{t("project.techStack")}</Label>
              <Input value={form.techStack} onChange={(e) => setForm({ ...form, techStack: e.target.value })} placeholder={t("project.techStackPlaceholder")} />
            </div>
          </div>
          <SheetFooter>
            <Button onClick={save} disabled={saving}>{saving ? t("common.saving") : t("common.save")}</Button>
          </SheetFooter>
        </SheetContent>
      </Sheet>
    </div>
  );
}

import React from "react";
import { Document, Page, Text, View, StyleSheet } from "@react-pdf/renderer";
import { Bullets, range, type TemplateProps } from "../common";
import { ensureFonts } from "../fonts";

// ats：美式 ATS（申请人追踪系统）优化英文简历。
// 设计原则：单栏、无照片/无年龄、关键词命中友好、量化成就前置。
// 字体用 NotoSansSC：同时覆盖 Latin 与 CJK，避免中国用户简历里的中文公司/学校/语言名被丢字。
// 分区标题用全大写（ATS 强信号），强调色仅用于标题下短横线。

const DEFAULT_ACCENT = "#111111";

const H = (label: string) => label; // 分区标题直接由调用方传入全大写英文

export function AtsTemplate({ resume, lang = "en", accent = DEFAULT_ACCENT }: TemplateProps) {
  ensureFonts();
  const b = resume.basics;

  // 联系方式：邮箱 · 手机 · 城市 · LinkedIn/个人站
  const contacts = [
    b.email,
    b.phone,
    b.location,
    ...(Array.isArray(b.profiles) ? b.profiles.map((p) => `${p.network}: ${p.url}`) : []),
  ].filter(Boolean);

  const s = StyleSheet.create({
    page: { fontFamily: "NotoSansSC", fontSize: 9.5, lineHeight: 1.45, color: "#111111", padding: 44 },
    name: { fontSize: 19, fontWeight: 700, letterSpacing: 0.5, textTransform: "uppercase" },
    label: { fontSize: 10.5, color: "#444", marginTop: 2 },
    contact: { fontSize: 8.5, color: "#555", marginTop: 4 },
    rule: { borderBottomWidth: 1, borderBottomColor: "#cccccc", marginTop: 8, marginBottom: 4 },
    section: { marginTop: 12 },
    sectionTitle: {
      fontSize: 10.5, fontWeight: 700, color: accent, letterSpacing: 1,
      borderBottomWidth: 1.2, borderBottomColor: accent, paddingBottom: 2, marginBottom: 6,
    },
    entry: { marginBottom: 8 },
    entryHead: { flexDirection: "row", justifyContent: "space-between", alignItems: "flex-end" },
    entryTitle: { fontWeight: 700, fontSize: 10 },
    entryMeta: { color: "#555", fontSize: 8.5, marginLeft: 8 },
    entrySub: { color: "#333", fontSize: 9, marginTop: 1 },
    summary: { color: "#222" },
    skillRow: { flexDirection: "row", flexWrap: "wrap" },
    skillChip: { fontSize: 8.5, color: "#222", marginRight: 6, marginBottom: 3 },
    bullets: { marginTop: 1 },
  });

  const Section = ({ title, children }: { title: string; children: React.ReactNode }) => (
    <View style={s.section}>
      <Text style={s.sectionTitle}>{H(title)}</Text>
      {children}
    </View>
  );

  return (
    <Document title={`${b.name} - Resume`} producer="CareerOS" creator="CareerOS">
      <Page size="LETTER" style={s.page}>
        <Text style={s.name}>{b.name}</Text>
        {b.label ? <Text style={s.label}>{b.label}</Text> : null}
        {contacts.length > 0 && <Text style={s.contact}>{contacts.join("  ·  ")}</Text>}
        <View style={s.rule} />

        {b.summary ? (
          <Section title="SUMMARY">
            <Text style={s.summary}>{b.summary}</Text>
          </Section>
        ) : null}

        {resume.work.length > 0 && (
          <Section title="EXPERIENCE">
            {resume.work.map((w, i) => (
              <View key={i} style={s.entry} wrap={false}>
                <View style={s.entryHead}>
                  <Text style={s.entryTitle}>{w.position}{w.name ? `, ${w.name}` : ""}</Text>
                  <Text style={s.entryMeta}>{range(w.startDate, w.endDate)}{w.location ? ` | ${w.location}` : ""}</Text>
                </View>
                {w.summary ? <Text style={s.entrySub}>{w.summary}</Text> : null}
                {w.highlights.length > 0 && (
                  <View style={s.bullets}>
                    <Bullets items={w.highlights} size={9} />
                  </View>
                )}
              </View>
            ))}
          </Section>
        )}

        {resume.projects.length > 0 && (
          <Section title="PROJECTS">
            {resume.projects.map((p, i) => (
              <View key={i} style={s.entry} wrap={false}>
                <View style={s.entryHead}>
                  <Text style={s.entryTitle}>{p.name}{p.roles.length ? ` (${p.roles.join(", ")})` : ""}</Text>
                  <Text style={s.entryMeta}>{range(p.startDate, p.endDate)}</Text>
                </View>
                {p.description ? <Text style={s.entrySub}>{p.description}</Text> : null}
                {p.highlights.length > 0 && (
                  <View style={s.bullets}>
                    <Bullets items={p.highlights} size={9} />
                  </View>
                )}
                {p.keywords.length ? (
                  <Text style={{ ...s.entryMeta, marginTop: 2 }}>Skills: {p.keywords.join(", ")}</Text>
                ) : null}
              </View>
            ))}
          </Section>
        )}

        {resume.skills.length > 0 && (
          <Section title="SKILLS">
            <View style={s.skillRow}>
              {resume.skills.map((sk, i) => (
                <Text key={i} style={s.skillChip}>
                  {sk.name}{sk.level && sk.level !== "0" ? ` (${sk.level})` : ""}
                </Text>
              ))}
            </View>
          </Section>
        )}

        {resume.awards.length > 0 && (
          <Section title="AWARDS & HONORS">
            <Bullets
              items={resume.awards.map((a) =>
                [a.title, a.issuer, a.date].filter(Boolean).join(", "),
              )}
              size={9}
            />
          </Section>
        )}

        {resume.education.length > 0 && (
          <Section title="EDUCATION">
            {resume.education.map((e, i) => (
              <View key={i} style={s.entry}>
                <View style={s.entryHead}>
                  <Text style={s.entryTitle}>{e.institution}</Text>
                  <Text style={s.entryMeta}>{range(e.startDate, e.endDate)}</Text>
                </View>
                <Text style={s.entrySub}>
                  {[e.studyType, e.area, e.score ? `GPA ${e.score}` : ""].filter(Boolean).join(", ")}
                </Text>
              </View>
            ))}
          </Section>
        )}

        {(() => {
          const langs = (resume as Record<string, unknown>)["x-meta"] as
            | { languages?: string[] }
            | undefined;
          const list = langs?.languages;
          return list && list.length > 0 ? (
            <Section title="LANGUAGES">
              <Text style={s.entrySub}>{list.join("  ·  ")}</Text>
            </Section>
          ) : null;
        })()}
      </Page>
    </Document>
  );
}

import React from "react";
import { Document, Page, Text, View, StyleSheet } from "@react-pdf/renderer";
import { ensureFonts } from "../fonts";
import { Bullets, contactLine, range, titlesFor, type TemplateProps } from "../common";

// classic：单栏经典排版，黑白为主，accent 仅用于分区标题下划线。

const DEFAULT_ACCENT = "#222222";

export function ClassicTemplate({ resume, lang = "zh", accent = DEFAULT_ACCENT }: TemplateProps) {
  ensureFonts();
  const t = titlesFor(lang);
  const b = resume.basics;

  const s = StyleSheet.create({
    page: { fontFamily: "NotoSansSC", fontSize: 9.5, lineHeight: 1.5, color: "#1a1a1a", padding: 42 },
    name: { fontSize: 20, fontWeight: 700, lineHeight: 1.2, marginBottom: 4 },
    label: { fontSize: 10.5, color: "#555" },
    contact: { fontSize: 8.5, color: "#666", marginTop: 4 },
    summary: { marginTop: 10, color: "#333" },
    section: { marginTop: 14 },
    sectionTitle: {
      fontSize: 11, fontWeight: 700, borderBottomWidth: 1, borderBottomColor: accent,
      paddingBottom: 3, marginBottom: 7,
    },
    entry: { marginBottom: 8 },
    entryHead: { flexDirection: "row", justifyContent: "space-between" },
    entryTitle: { fontWeight: 700, fontSize: 10 },
    entryMeta: { color: "#666", fontSize: 8.5 },
    entrySub: { color: "#444", fontSize: 9, marginTop: 1 },
    skillRow: { flexDirection: "row", flexWrap: "wrap" },
    skillChip: {
      fontSize: 8.5, backgroundColor: "#f0f0f0", borderRadius: 3,
      paddingHorizontal: 6, paddingVertical: 2, marginRight: 4, marginBottom: 4,
    },
  });

  const Section = ({ title, children }: { title: string; children: React.ReactNode }) => (
    <View style={s.section}>
      <Text style={s.sectionTitle}>{title}</Text>
      {children}
    </View>
  );

  return (
    <Document title={`${b.name} - Resume`} producer="CareerOS" creator="CareerOS">
      <Page size="A4" style={s.page}>
        <Text style={s.name}>{b.name}</Text>
        {b.label ? <Text style={s.label}>{b.label}</Text> : null}
        {contactLine(b) ? <Text style={s.contact}>{contactLine(b)}</Text> : null}
        {b.summary ? <Text style={s.summary}>{b.summary}</Text> : null}

        {resume.work.length > 0 && (
          <Section title={t.work}>
            {resume.work.map((w, i) => (
              <View key={i} style={s.entry} wrap={false}>
                <View style={s.entryHead}>
                  <Text style={s.entryTitle}>{w.name}{w.position ? `｜${w.position}` : ""}</Text>
                  <Text style={s.entryMeta}>{range(w.startDate, w.endDate)}{w.location ? `｜${w.location}` : ""}</Text>
                </View>
                {w.summary ? <Text style={s.entrySub}>{w.summary}</Text> : null}
                <Bullets items={w.highlights} />
              </View>
            ))}
          </Section>
        )}

        {resume.projects.length > 0 && (
          <Section title={t.projects}>
            {resume.projects.map((p, i) => (
              <View key={i} style={s.entry} wrap={false}>
